from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if all(row[c] == 2 for row in grid))
    left_bg = Counter(grid[r][c] for r in range(h) for c in range(sep)).most_common(1)[0][0]
    right_bg = Counter(grid[r][c] for r in range(h) for c in range(sep + 1, w)).most_common(1)[0][0]

    return [
        [
            2 if grid[r][c] != left_bg or grid[r][sep + 1 + c] != right_bg else 3
            for c in range(sep)
        ]
        for r in range(h)
    ]
